selector_to_html = {"a[href=\"#step-1-install-flagtree-iluvatar-backend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.4 Step 1: Install FlagTree (Iluvatar backend)<a class=\"headerlink\" href=\"#step-1-install-flagtree-iluvatar-backend\" title=\"Link to this heading\">#</a></h3><h4>What is FlagTree<a class=\"headerlink\" href=\"#what-is-flagtree\" title=\"Link to this heading\">#</a></h4><p>FlagTree is a unified multi-chip compiler based on Triton. For Iluvatar BV150, FlagTree provides the <strong>iluvatar backend</strong>, compiling Triton DSL into CoreX IR \u2192 Iluvatar GPU machine code.</p>", "a[href=\"#network-configuration\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Network configuration<a class=\"headerlink\" href=\"#network-configuration\" title=\"Link to this heading\">#</a></h4><p>Days cluster typically cannot access GitHub or HuggingFace directly. Configure mirror sources:</p>", "a[href=\"#from-modelscope-recommended-domestic-access\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.1 From ModelScope (recommended, domestic access)<a class=\"headerlink\" href=\"#from-modelscope-recommended-domestic-access\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#bv150-required-environment-variables\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">BV150 required environment variables<a class=\"headerlink\" href=\"#bv150-required-environment-variables\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#run-in-docker-container\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.2 Run in Docker container<a class=\"headerlink\" href=\"#run-in-docker-container\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#samplingparams-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.2 SamplingParams parameters<a class=\"headerlink\" href=\"#samplingparams-parameters\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#q7-modulenotfounderror-no-module-named-triton\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q7: <code class=\"docutils literal notranslate\"><span class=\"pre\">ModuleNotFoundError:</span> <span class=\"pre\">No</span> <span class=\"pre\">module</span> <span class=\"pre\">named</span> <span class=\"pre\">'triton'</span></code><a class=\"headerlink\" href=\"#q7-modulenotfounderror-no-module-named-triton\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: FlagTree installed without backend suffix.</p><p><strong>Solution</strong>: Use <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree===0.5.1+iluvatar3.1</span></code> (with <code class=\"docutils literal notranslate\"><span class=\"pre\">+iluvatar</span></code> suffix).</p>", "a[href=\"#install-build-dependencies\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Install build dependencies<a class=\"headerlink\" href=\"#install-build-dependencies\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#benchmark-performance\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Benchmark performance<a class=\"headerlink\" href=\"#benchmark-performance\" title=\"Link to this heading\">#</a></h2><h3>8.1 Expected performance of Qwen2.5-1.5B on BV150<a class=\"headerlink\" href=\"#expected-performance-of-qwen2-5-1-5b-on-bv150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#expected-performance-of-qwen2-5-1-5b-on-bv150\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.1 Expected performance of Qwen2.5-1.5B on BV150<a class=\"headerlink\" href=\"#expected-performance-of-qwen2-5-1-5b-on-bv150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id1\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#expected-output\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.3 Expected output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#qwen2-5-1-5b-inference-on-iluvatar-bi-v150\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Qwen2.5-1.5B inference on Iluvatar BI-V150<a class=\"headerlink\" href=\"#qwen2-5-1-5b-inference-on-iluvatar-bi-v150\" title=\"Link to this heading\">#</a></h1><h2>Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#model-download\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Model download<a class=\"headerlink\" href=\"#model-download\" title=\"Link to this heading\">#</a></h2><h3>4.1 From ModelScope (recommended, domestic access)<a class=\"headerlink\" href=\"#from-modelscope-recommended-domestic-access\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#bv150-specific-optimization\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.3 BV150-specific optimization<a class=\"headerlink\" href=\"#bv150-specific-optimization\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#step-3-install-flaggems\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.6 Step 3: Install FlagGems<a class=\"headerlink\" href=\"#step-3-install-flaggems\" title=\"Link to this heading\">#</a></h3><h4>What is FlagGems<a class=\"headerlink\" href=\"#what-is-flaggems\" title=\"Link to this heading\">#</a></h4><p>FlagGems is a high-performance unified operator library based on Triton. Through PyTorch ATen registration, it <strong>automatically replaces</strong> operators in <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.*</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.nn.functional.*</span></code> with optimized Triton implementations.</p><p>For Iluvatar BV150, FlagGems compiles standard PyTorch operators (mm, softmax, rms_norm, etc.) into CoreX IR for execution.</p>", "a[href=\"#q5-runtimeerror-no-hip-gpus-are-available\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q5: <code class=\"docutils literal notranslate\"><span class=\"pre\">RuntimeError:</span> <span class=\"pre\">No</span> <span class=\"pre\">HIP</span> <span class=\"pre\">GPUs</span> <span class=\"pre\">are</span> <span class=\"pre\">available</span></code><a class=\"headerlink\" href=\"#q5-runtimeerror-no-hip-gpus-are-available\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: FlagGems imported before CUDA/CoreX initialization.</p><p><strong>Solution</strong>:</p>", "a[href=\"#id6\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#environment-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Environment requirements<a class=\"headerlink\" href=\"#environment-requirements\" title=\"Link to this heading\">#</a></h2><h3>2.1 Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h3><p>Ensure FlagOS components are installed:</p>", "a[href=\"#huggingface-modelscope-paths\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">HuggingFace / ModelScope paths<a class=\"headerlink\" href=\"#huggingface-modelscope-paths\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#direct-run\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6.1 Direct run<a class=\"headerlink\" href=\"#direct-run\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#what-is-flaggems\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What is FlagGems<a class=\"headerlink\" href=\"#what-is-flaggems\" title=\"Link to this heading\">#</a></h4><p>FlagGems is a high-performance unified operator library based on Triton. Through PyTorch ATen registration, it <strong>automatically replaces</strong> operators in <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.*</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.nn.functional.*</span></code> with optimized Triton implementations.</p><p>For Iluvatar BV150, FlagGems compiles standard PyTorch operators (mm, softmax, rms_norm, etc.) into CoreX IR for execution.</p>", "a[href=\"#step-2-install-vllm-corex-customized-version\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.5 Step 2: Install vLLM (CoreX customized version)<a class=\"headerlink\" href=\"#step-2-install-vllm-corex-customized-version\" title=\"Link to this heading\">#</a></h3><h4>Get vllm-corex<a class=\"headerlink\" href=\"#get-vllm-corex\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#required-vs-optional-components\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 Required vs optional components<a class=\"headerlink\" href=\"#required-vs-optional-components\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#model-info\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Model info<a class=\"headerlink\" href=\"#model-info\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#serving-mode-vllm-api-server\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.3 Serving mode (vLLM API Server)<a class=\"headerlink\" href=\"#serving-mode-vllm-api-server\" title=\"Link to this heading\">#</a></h3><p>Client request:</p>", "a[href=\"#id4\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#what-is-flagcx\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What is FlagCX<a class=\"headerlink\" href=\"#what-is-flagcx\" title=\"Link to this heading\">#</a></h4><p>FlagCX is a unified multi-chip communication library. For BV150, it uses <strong>IXCCL</strong> (Iluvatar communication library) backend, supporting multi-card homogeneous communication and cross-chip heterogeneous communication.</p>", "a[href=\"#q4-model-download-fails-network-restricted\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q4: Model download fails (network restricted)<a class=\"headerlink\" href=\"#q4-model-download-fails-network-restricted\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Days cluster cannot access HuggingFace.</p><p><strong>Solution</strong>:</p>", "a[href=\"#parameter-tuning\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Parameter tuning<a class=\"headerlink\" href=\"#parameter-tuning\" title=\"Link to this heading\">#</a></h2><h3>7.1 LLM initialization parameters<a class=\"headerlink\" href=\"#llm-initialization-parameters\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#component-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 Component dependencies<a class=\"headerlink\" href=\"#component-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id7\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#get-vllm-corex\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Get vllm-corex<a class=\"headerlink\" href=\"#get-vllm-corex\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#modelscope-cache-directory-structure\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.2 ModelScope cache directory structure<a class=\"headerlink\" href=\"#modelscope-cache-directory-structure\" title=\"Link to this heading\">#</a></h3><p>After download, model files are located at:</p>", "a[href=\"#q9-vendor-iluvatar-not-found-in-vendor-device-map\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q9: <code class=\"docutils literal notranslate\"><span class=\"pre\">Vendor</span> <span class=\"pre\">'iluvatar'</span> <span class=\"pre\">not</span> <span class=\"pre\">found</span> <span class=\"pre\">in</span> <span class=\"pre\">VENDOR_DEVICE_MAP</span></code><a class=\"headerlink\" href=\"#q9-vendor-iluvatar-not-found-in-vendor-device-map\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: vllm-plugin-FL version too old.</p><p><strong>Solution</strong>: Upgrade to latest version.</p>", "a[href=\"#install\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#install\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#basic-inference-script\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.1 Basic inference script<a class=\"headerlink\" href=\"#basic-inference-script\" title=\"Link to this heading\">#</a></h3><p>Create <code class=\"docutils literal notranslate\"><span class=\"pre\">run_qwen2.5_1.5b.py</span></code>:</p>", "a[href=\"#verify-gpu-availability\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify GPU availability<a class=\"headerlink\" href=\"#verify-gpu-availability\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#faq\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. FAQ<a class=\"headerlink\" href=\"#faq\" title=\"Link to this heading\">#</a></h2><h3>Q1: Model load fails with <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code> error<a class=\"headerlink\" href=\"#q1-model-load-fails-with-symmetric-memory-error\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Unsupported symbol in torch-corex. vLLM\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">parallel_state.py</span></code> attempts to import <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code>.</p><p><strong>Solution</strong>:</p>", "a[href=\"#inference-scripts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Inference scripts<a class=\"headerlink\" href=\"#inference-scripts\" title=\"Link to this heading\">#</a></h2><h3>5.1 Basic inference script<a class=\"headerlink\" href=\"#basic-inference-script\" title=\"Link to this heading\">#</a></h3><p>Create <code class=\"docutils literal notranslate\"><span class=\"pre\">run_qwen2.5_1.5b.py</span></code>:</p>", "a[href=\"#usage\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Usage<a class=\"headerlink\" href=\"#usage\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#docker-image-recommended-alternative\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Docker image (recommended alternative)<a class=\"headerlink\" href=\"#docker-image-recommended-alternative\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#id5\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#q1-model-load-fails-with-symmetric-memory-error\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q1: Model load fails with <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code> error<a class=\"headerlink\" href=\"#q1-model-load-fails-with-symmetric-memory-error\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Unsupported symbol in torch-corex. vLLM\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">parallel_state.py</span></code> attempts to import <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code>.</p><p><strong>Solution</strong>:</p>", "a[href=\"#environment-variables\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Environment variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#vllm-version-compatibility\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">vLLM version compatibility<a class=\"headerlink\" href=\"#vllm-version-compatibility\" title=\"Link to this heading\">#</a></h3><p><strong>BV150 must use v0.13.0 series vllm-corex.</strong></p>", "a[href=\"#q3-inference-speed-much-slower-than-expected\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q3: Inference speed much slower than expected<a class=\"headerlink\" href=\"#q3-inference-speed-much-slower-than-expected\" title=\"Link to this heading\">#</a></h3><p><strong>Checklist</strong>:</p>", "a[href=\"#network-restricted-environment-alternatives\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Network-restricted environment alternatives<a class=\"headerlink\" href=\"#network-restricted-environment-alternatives\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#model-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Model overview<a class=\"headerlink\" href=\"#model-overview\" title=\"Link to this heading\">#</a></h2><p><strong>Qwen2.5-1.5B</strong> is a small-scale language model from the Alibaba Qwen2.5 series, with approximately 1.5 billion parameters.</p>", "a[href=\"#running-instructions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Running instructions<a class=\"headerlink\" href=\"#running-instructions\" title=\"Link to this heading\">#</a></h2><h3>6.1 Direct run<a class=\"headerlink\" href=\"#direct-run\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#step-0-basic-environment-setup\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 Step 0: Basic environment setup<a class=\"headerlink\" href=\"#step-0-basic-environment-setup\" title=\"Link to this heading\">#</a></h3><h4>System requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#step-4-install-vllm-plugin-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.7 Step 4: Install vllm-plugin-FL<a class=\"headerlink\" href=\"#step-4-install-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h3><h4>What is vllm-plugin-FL<a class=\"headerlink\" href=\"#what-is-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h4><p>vllm-plugin-FL is the <strong>core dispatch plugin</strong> of the FlagOS ecosystem, responsible for:</p>", "a[href=\"#inference-script-with-flaggems\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.2 Inference script with FlagGems<a class=\"headerlink\" href=\"#inference-script-with-flaggems\" title=\"Link to this heading\">#</a></h3><p>To explicitly enable FlagGems operator acceleration:</p>", "a[href=\"#q2-oom-out-of-memory-during-inference\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q2: OOM (Out of Memory) during inference<a class=\"headerlink\" href=\"#q2-oom-out-of-memory-during-inference\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Model + KV Cache exceeds BV150 memory capacity.</p><p><strong>Solution</strong>:</p>", "a[href=\"#step-6-environment-variables-and-verification\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.9 Step 6: Environment variables and verification<a class=\"headerlink\" href=\"#step-6-environment-variables-and-verification\" title=\"Link to this heading\">#</a></h3><h4>BV150 required environment variables<a class=\"headerlink\" href=\"#bv150-required-environment-variables\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#id2\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Install<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#system-requirements\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">System requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#q8-libcudart-so-12-not-found\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q8: <code class=\"docutils literal notranslate\"><span class=\"pre\">libcudart.so.12</span></code> not found<a class=\"headerlink\" href=\"#q8-libcudart-so-12-not-found\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Upstream vLLM used instead of vllm-corex.</p><p><strong>Solution</strong>: Must use vllm-corex.</p>", "a[href=\"#docker-image-recommendations\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Docker image recommendations<a class=\"headerlink\" href=\"#docker-image-recommendations\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#llm-initialization-parameters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.1 LLM initialization parameters<a class=\"headerlink\" href=\"#llm-initialization-parameters\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#what-is-vllm-plugin-fl\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What is vllm-plugin-FL<a class=\"headerlink\" href=\"#what-is-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h4><p>vllm-plugin-FL is the <strong>core dispatch plugin</strong> of the FlagOS ecosystem, responsible for:</p>", "a[href=\"#prerequisites\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h3><p>Ensure FlagOS components are installed:</p>", "a[href=\"#verify\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Verify<a class=\"headerlink\" href=\"#verify\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#what-is-flagtree\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">What is FlagTree<a class=\"headerlink\" href=\"#what-is-flagtree\" title=\"Link to this heading\">#</a></h4><p>FlagTree is a unified multi-chip compiler based on Triton. For Iluvatar BV150, FlagTree provides the <strong>iluvatar backend</strong>, compiling Triton DSL into CoreX IR \u2192 Iluvatar GPU machine code.</p>", "a[href=\"#from-huggingface-requires-internet-access\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.3 From HuggingFace (requires internet access)<a class=\"headerlink\" href=\"#from-huggingface-requires-internet-access\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#performance-factors\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">8.2 Performance factors<a class=\"headerlink\" href=\"#performance-factors\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#q6-output-is-garbled-or-meaningless\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Q6: Output is garbled or meaningless<a class=\"headerlink\" href=\"#q6-output-is-garbled-or-meaningless\" title=\"Link to this heading\">#</a></h3><p><strong>Checklist</strong>:</p>", "a[href=\"#full-verification-script\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Full verification script<a class=\"headerlink\" href=\"#full-verification-script\" title=\"Link to this heading\">#</a></h4><p>Create <code class=\"docutils literal notranslate\"><span class=\"pre\">verify_flagos.py</span></code>:</p>", "a[href=\"#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h2><h3>3.1 Component dependencies<a class=\"headerlink\" href=\"#component-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#step-5-optional-install-flagcx\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.8 Step 5: (Optional) Install FlagCX<a class=\"headerlink\" href=\"#step-5-optional-install-flagcx\" title=\"Link to this heading\">#</a></h3><h4>What is FlagCX<a class=\"headerlink\" href=\"#what-is-flagcx\" title=\"Link to this heading\">#</a></h4><p>FlagCX is a unified multi-chip communication library. For BV150, it uses <strong>IXCCL</strong> (Iluvatar communication library) backend, supporting multi-card homogeneous communication and cross-chip heterogeneous communication.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
